create table usuario (fecha_creacion timestamp(6) not null, id bigint generated by default as identity, version bigint not null, estado varchar(20) not null check ((estado in ('ACTIVO','BAJA'))), rol varchar(20) not null check ((rol in ('USER','ADMIN'))), password_hash varchar(100) not null, nombre varchar(150) not null, email varchar(254) not null unique, primary key (id));
